=== FILE: credit_counter_formal.sv ===
// Formal properties for credit_counter, written against interface_spec.md.
// Immediate assertions only (assert/cover inside always blocks, if-guarded,
// $past guarded by a first-cycle flag), as read by Yosys read -formal.
// No assume statements: every input is free.
`default_nettype none

module credit_counter_check #(
    parameter integer MAX = 4
) (
    input  wire       clk,
    input  wire       rst_n,
    input  wire       take,
    input  wire       give,
    output wire [7:0] credits,
    output wire       avail,
    output wire       full,
    output wire       err,
    output wire       reset_seen
);
    localparam [7:0] F_MAX = MAX;

    credit_counter #(
        .MAX(MAX)
    ) dut (
        .clk    (clk),
        .rst_n  (rst_n),
        .take   (take),
        .give   (give),
        .credits(credits),
        .avail  (avail),
        .full   (full),
        .err    (err)
    );

    // First-cycle guard for $past, and a flag that a reset has been applied.
    reg f_past_valid = 1'b0;
    reg f_reset_seen = 1'b0;
    always @(posedge clk) begin
        f_past_valid <= 1'b1;
        if (!rst_n)
            f_reset_seen <= 1'b1;
    end
    assign reset_seen = f_reset_seen;

    // [req:CC-STATUS] avail and full follow credits with no clock edge.
    always @(*) begin
        assert (avail == (credits != 8'd0));
        assert (full == (credits == F_MAX));
    end

    always @(posedge clk) begin
        // [req:CC-RANGE] after reset, credits never exceeds MAX.
        if (f_reset_seen)
            assert (credits <= F_MAX);

        // [req:CC-RESET]
        if (f_past_valid && !$past(rst_n))
            assert (credits == F_MAX);
        if (f_past_valid && !$past(rst_n))
            assert (!err);

        // [req:CC-TAKE] take only, credits above zero: down by one, no refusal.
        if (f_past_valid && $past(rst_n) && $past(take) && !$past(give) && ($past(credits) != 8'd0))
            assert (credits == $past(credits) - 8'd1);
        if (f_past_valid && $past(rst_n) && $past(take) && !$past(give) && ($past(credits) != 8'd0))
            assert (err == $past(err));

        // [req:CC-GIVE] give only, credits below MAX: up by one, no refusal.
        if (f_past_valid && $past(rst_n) && $past(give) && !$past(take) && ($past(credits) < F_MAX))
            assert (credits == $past(credits) + 8'd1);
        if (f_past_valid && $past(rst_n) && $past(give) && !$past(take) && ($past(credits) < F_MAX))
            assert (err == $past(err));

        // [req:CC-BOTH] take and give together: no change, nothing refused.
        if (f_past_valid && $past(rst_n) && $past(take) && $past(give))
            assert (credits == $past(credits));
        if (f_past_valid && $past(rst_n) && $past(take) && $past(give))
            assert (err == $past(err));

        // [req:CC-IDLE] neither: no change, nothing refused.
        if (f_past_valid && $past(rst_n) && !$past(take) && !$past(give))
            assert (credits == $past(credits));
        if (f_past_valid && $past(rst_n) && !$past(take) && !$past(give))
            assert (err == $past(err));

        // [req:CC-UNDERFLOW] take only at zero: refused, stays zero, err set.
        if (f_past_valid && $past(rst_n) && $past(take) && !$past(give) && ($past(credits) == 8'd0))
            assert (credits == 8'd0);
        if (f_past_valid && $past(rst_n) && $past(take) && !$past(give) && ($past(credits) == 8'd0))
            assert (err);

        // [req:CC-OVERFLOW] give only at MAX: refused, stays MAX, err set.
        if (f_past_valid && $past(rst_n) && $past(give) && !$past(take) && ($past(credits) == F_MAX))
            assert (credits == F_MAX);
        if (f_past_valid && $past(rst_n) && $past(give) && !$past(take) && ($past(credits) == F_MAX))
            assert (err);

        // [req:CC-ERR-STICKY] once set, err stays until reset.
        if (f_past_valid && $past(rst_n) && $past(err))
            assert (err);
    end

    // Shallow covers valid for every MAX, reached from reset.
    always @(posedge clk) begin
        cover (f_reset_seen && full);
        cover (f_reset_seen && rst_n && (credits != F_MAX));
        cover (f_reset_seen && err);
    end
endmodule

module credit_counter_formal (
    input wire clk,
    input wire rst_n_1,
    input wire take_1,
    input wire give_1,
    input wire rst_n_4,
    input wire take_4,
    input wire give_4,
    input wire rst_n_5,
    input wire take_5,
    input wire give_5,
    input wire rst_n_255,
    input wire take_255,
    input wire give_255
);
    wire [7:0] credits_1, credits_4, credits_5, credits_255;
    wire avail_1, avail_4, avail_5, avail_255;
    wire full_1, full_4, full_5, full_255;
    wire err_1, err_4, err_5, err_255;
    wire rs_1, rs_4, rs_5, rs_255;

    // [req:CC-PARAM] smallest MAX, default, non-power-of-two, largest MAX.
    credit_counter_check #(.MAX(1)) chk_1 (
        .clk(clk), .rst_n(rst_n_1), .take(take_1), .give(give_1),
        .credits(credits_1), .avail(avail_1), .full(full_1), .err(err_1),
        .reset_seen(rs_1)
    );
    credit_counter_check #(.MAX(4)) chk_4 (
        .clk(clk), .rst_n(rst_n_4), .take(take_4), .give(give_4),
        .credits(credits_4), .avail(avail_4), .full(full_4), .err(err_4),
        .reset_seen(rs_4)
    );
    credit_counter_check #(.MAX(5)) chk_5 (
        .clk(clk), .rst_n(rst_n_5), .take(take_5), .give(give_5),
        .credits(credits_5), .avail(avail_5), .full(full_5), .err(err_5),
        .reset_seen(rs_5)
    );
    credit_counter_check #(.MAX(255)) chk_255 (
        .clk(clk), .rst_n(rst_n_255), .take(take_255), .give(give_255),
        .credits(credits_255), .avail(avail_255), .full(full_255), .err(err_255),
        .reset_seen(rs_255)
    );

    // Scenario covers, reached from reset, that the proof must still allow.
    always @(posedge clk) begin
        // MAX = 1
        cover (rs_1 && !avail_1 && rst_n_1 && take_1 && !give_1);
        cover (rs_1 && !avail_1 && rst_n_1 && take_1 && give_1);
        cover (rs_1 && full_1 && rst_n_1 && take_1 && give_1);
        cover (rs_1 && full_1 && rst_n_1 && give_1 && !take_1);

        // MAX = 4
        cover (rs_4 && (credits_4 == 8'd0) && rst_n_4 && take_4 && !give_4);
        cover (rs_4 && (credits_4 == 8'd0) && rst_n_4 && take_4 && give_4);
        cover (rs_4 && full_4 && rst_n_4 && take_4 && give_4);
        cover (rs_4 && full_4 && rst_n_4 && give_4 && !take_4);
        cover (rs_4 && (credits_4 == 8'd0) && err_4 && rst_n_4 && give_4 && !take_4);

        // MAX = 5 (not a power of two)
        cover (rs_5 && (credits_5 == 8'd0) && rst_n_5 && take_5 && !give_5);
        cover (rs_5 && (credits_5 == 8'd0) && rst_n_5 && take_5 && give_5);
        cover (rs_5 && full_5 && rst_n_5 && take_5 && give_5);
        cover (rs_5 && (credits_5 == 8'd3) && err_5);

        // MAX = 255 (shallow scenarios only within the depth)
        cover (rs_255 && full_255 && rst_n_255 && give_255 && !take_255);
        cover (rs_255 && full_255 && rst_n_255 && take_255 && give_255);
        cover (rs_255 && (credits_255 == 8'd254) && rst_n_255 && give_255 && !take_255);
    end
endmodule

`default_nettype wire
=== END FILE ===
